import{_ as l,a0 as o,w as d,s as r,ao as p,I as t,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"用 testdisk 恢复 Linux 上已删除的文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 testdisk 恢复 Linux 上已删除的文件 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 testdisk 恢复 Linux 上已删除的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 testdisk 恢复 Linux 上已删除的文件 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200930 Recovering deleted files on Linux with testdisk","title":"用 testdisk 恢复 Linux 上已删除的文件","tag":"202010","desc":""},"relativePath":"202010/20200930 Recovering deleted files on Linux with testdisk.md","filePath":"[post].md"}'),c={name:"202010/20200930 Recovering deleted files on Linux with testdisk.md"};function h(k,s,g,u,b,f){const n=o("Link");return d(),r("div",null,[s[18]||(s[18]=p('<h1 id="用-testdisk-恢复-linux-上已删除的文件" tabindex="-1">用 testdisk 恢复 Linux 上已删除的文件 <a class="header-anchor" href="#用-testdisk-恢复-linux-上已删除的文件" aria-label="Permalink to “用 testdisk 恢复 Linux 上已删除的文件”">​</a></h1><blockquote><p>这篇文章介绍了 testdisk，这是恢复最近删除的文件（以及用其他方式修复分区）的工具之一，非常方便。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/01/survival_life-preserver_risk_swimming_rescue-100747102-large.jpg" alt=""></p><p>当你在 Linux 系统上删除一个文件时，它不一定会永远消失，特别是当你最近才刚刚删除了它的时候。</p><p>除非你用 <code>shred</code> 等工具把它擦掉，否则数据仍然会放在你的磁盘上 —— 而恢复已删除文件的最佳工具之一 <code>testdisk</code> 可以帮助你拯救它。虽然 <code>testdisk</code> 具有广泛的功能，包括恢复丢失或损坏的分区和使不能启动磁盘可以重新启动，但它也经常被用来恢复被误删的文件。</p><p>在本篇文章中，我们就来看看如何使用 <code>testdisk</code> 恢复已删除的文件，以及该过程中的每一步是怎样的。由于这个过程需要不少的步骤，所以当你做了几次之后，你可能会觉得操作起来会更加得心应手。</p><h3 id="安装-testdisk" tabindex="-1">安装 testdisk <a class="header-anchor" href="#安装-testdisk" aria-label="Permalink to “安装 testdisk”">​</a></h3><p>可以使用 <code>apt install testdisk</code> 或 <code>yum install testdisk</code> 等命令安装 <code>testdisk</code>。有趣的是，它不仅是一个 Linux 工具，而且还适用于 MacOS、Solaris 和 Windows。</p>',8)),t("p",null,[s[1]||(s[1]=e("文档可在 ",-1)),a(n,{href:"https://www.cgsecurity.org/testdisk.pdf"},{default:i(()=>[...s[0]||(s[0]=[e("cgsecurity.org",-1)])]),_:1}),s[2]||(s[2]=e(" 中找到。",-1))]),s[19]||(s[19]=p(`<h3 id="恢复文件" tabindex="-1">恢复文件 <a class="header-anchor" href="#恢复文件" aria-label="Permalink to “恢复文件”">​</a></h3><p>首先，你必须以 <code>root</code> 身份登录，或者有 <code>sudo</code> 权限才能使用 <code>testdisk</code>。如果你没有 <code>sudo</code> 访问权限，你会在这个过程一开始就被踢出，而如果你选择创建了一个日志文件的话，最终会有这样的消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TestDisk exited normally.</span></span>
<span class="line"><span>jdoe is not in the sudoers file.  This incident will be reported.</span></span></code></pre></div><p>当你用 <code>testdisk</code> 恢复被删除的文件时，你最终会将恢复的文件放在你启动该工具的目录下，而这些文件会属于 <code>root</code>。出于这个原因，我喜欢在 <code>/home/recovery</code> 这样的目录下启动。一旦文件被成功地还原和验证，就可以将它们移回它们的所属位置，并将它们的所有权也恢复。</p><p>在你可以写入的选定目录下开始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /home/recovery</span></span>
<span class="line"><span>$ testdisk</span></span></code></pre></div><p><code>testdisk</code> 提供的第一页信息描述了该工具并显示了一些选项。至少在刚开始，创建个日志文件是个好主意，因为它提供的信息可能会被证明是有用的。下面是如何做的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Use arrow keys to select, then press Enter key:</span></span>
<span class="line"><span>&gt;[ Create ] Create a new log file</span></span>
<span class="line"><span> [ Append ] Append information to log file</span></span>
<span class="line"><span> [ No Log ] Don’t record anything</span></span></code></pre></div><p>左边的 <code>&gt;</code> 以及你看到的反转的字体和背景颜色指出了你按下回车键后将使用的选项。在这个例子中，我们选择了创建日志文件。</p><p>然后会提示你输入密码（除非你最近使用过 <code>sudo</code>）。</p><p>下一步是选择被删除文件所存储的磁盘分区（如果没有高亮显示的话）。根据需要使用上下箭头移动到它。然后点两次右箭头，当 “Proceed” 高亮显示时按回车键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Select a media (use Arrow keys, then press Enter):</span></span>
<span class="line"><span> Disk /dev/sda - 120 GB / 111 GiB - SSD2SC120G1CS1754D117-551</span></span>
<span class="line"><span>&gt;Disk /dev/sdb - 500 GB / 465 GiB - SAMSUNG HE502HJ</span></span>
<span class="line"><span> Disk /dev/loop0 - 13 MB / 13 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop1 - 101 MB / 96 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop10 - 148 MB / 141 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop11 - 36 MB / 35 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop12 - 52 MB / 49 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop13 - 78 MB / 75 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop14 - 173 MB / 165 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop15 - 169 MB / 161 MiB (RO)</span></span>
<span class="line"><span>&gt;[Previous]  [  Next  ]  [Proceed ]  [  Quit  ]</span></span></code></pre></div><p>在这个例子中，被删除的文件在 <code>/dev/sdb</code> 的主目录下。</p><p>此时，<code>testdisk</code> 应该已经选择了合适的分区类型。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Disk /dev/sdb - 500 GB / 465 GiB - SAMSUNG HE502HJ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please select the partition table type, press Enter when done.</span></span>
<span class="line"><span> [Intel  ] Intel/PC partition</span></span>
<span class="line"><span>&gt;[EFI GPT] EFI GPT partition map (Mac i386, some x86_64...)</span></span>
<span class="line"><span> [Humax  ] Humax partition table</span></span>
<span class="line"><span> [Mac    ] Apple partition map (legacy)</span></span>
<span class="line"><span> [None   ] Non partitioned media</span></span>
<span class="line"><span> [Sun    ] Sun Solaris partition</span></span>
<span class="line"><span> [XBox   ] XBox partition</span></span>
<span class="line"><span> [Return ] Return to disk selection</span></span></code></pre></div><p>在下一步中，按向下箭头指向 “[ Advanced ] Filesystem Utils”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ Analyse  ] Analyse current partition structure and search for lost partitions</span></span>
<span class="line"><span>&gt;[ Advanced ] Filesystem Utils</span></span>
<span class="line"><span> [ Geometry ] Change disk geometry</span></span>
<span class="line"><span> [ Options  ] Modify options</span></span>
<span class="line"><span> [ Quit     ] Return to disk selection</span></span></code></pre></div><p>接下来，查看选定的分区。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Partition                  Start        End    Size in sectors</span></span>
<span class="line"><span>&gt; 1 P Linux filesys. data         2048  910155775  910153728 [drive2]</span></span></code></pre></div><p>然后按右箭头选择底部的 “[ List ]”，按回车键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[  Type  ]  [Superblock] &gt;[  List  ]  [Image Creation]  [  Quit  ]</span></span></code></pre></div><p>请注意，它看起来就像我们从根目录 <code>/</code> 开始，但实际上这是我们正在工作的文件系统的基点。在这个例子中，就是 <code>/home</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Directory /   &lt;== 开始点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;drwxr-xr-x     0     0      4096 23-Sep-2020 17:46 .</span></span>
<span class="line"><span> drwxr-xr-x     0     0      4096 23-Sep-2020 17:46 ..</span></span>
<span class="line"><span> drwx———     0     0     16384 22-Sep-2020 11:30 lost+found</span></span>
<span class="line"><span> drwxr-xr-x  1008  1008      4096  9-Jul-2019 14:10 dorothy</span></span>
<span class="line"><span> drwxr-xr-x  1001  1001      4096 22-Sep-2020 12:12 nemo</span></span>
<span class="line"><span> drwxr-xr-x  1005  1005      4096 19-Jan-2020 11:49 eel</span></span>
<span class="line"><span> drwxrwxrwx     0     0      4096 25-Sep-2020 08:08 recovery</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>接下来，我们按箭头指向具体的主目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxr-xr-x  1016  1016      4096 17-Feb-2020 16:40 gino</span></span>
<span class="line"><span>&gt;drwxr-xr-x  1000  1000     20480 25-Sep-2020 08:00 shs</span></span></code></pre></div><p>按回车键移动到该目录，然后根据需要向下箭头移动到子目录。注意，如果选错了，可以选择列表顶部附近的 <code>..</code> 返回。</p><p>如果找不到文件，可以按 <code>/</code>（就像在 <code>vi</code> 中开始搜索时一样），提示你输入文件名或其中的一部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Directory /shs     &lt;== current location</span></span>
<span class="line"><span>                                                   Previous</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span> -rw-rw-r—  1000  1000       426  8-Apr-2019 19:09 2-min-topics</span></span>
<span class="line"><span>&gt;-rw-rw-r—  1000  1000     24667  8-Feb-2019 08:57 Up_on_the_Roof.pdf</span></span></code></pre></div><p>一旦你找到需要恢复的文件，按 <code>c</code> 选择它。</p><p>注意：你会在屏幕底部看到有用的说明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Use Left arrow to go back, Right to change directory, h to hide deleted files</span></span>
<span class="line"><span>    q to quit, : to select the current file, a to select all files</span></span>
<span class="line"><span>    C to copy the selected files, c to copy the current file &lt;==</span></span></code></pre></div><p>这时，你就可以在起始目录内选择恢复该文件的位置了（参见前面的说明，在将文件移回原点之前，先在一个合适的地方进行检查）。在这种情况下，<code>/home/recovery</code> 目录没有子目录，所以这就是我们的恢复点。</p><p>注意：你会在屏幕底部看到有用的说明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please select a destination where /shs/Up_on_the_Roof.pdf will be copied.</span></span>
<span class="line"><span>Keys: Arrow keys to select another directory</span></span>
<span class="line"><span>      C when the destination is correct</span></span>
<span class="line"><span>      Q to quit</span></span>
<span class="line"><span>Directory /home/recovery    &lt;== 恢复位置</span></span></code></pre></div><p>一旦你看到 “Copy done! 1 ok, 0 failed” 的绿色字样，你就会知道文件已经恢复了。</p><p>在这种情况下，文件被留在 <code>/home/recovery/shs</code> 下（起始目录，附加所选目录）。</p><p>在将文件移回原来的位置之前，你可能应该先验证恢复的文件看起来是否正确。确保你也恢复了原来的所有者和组，因为此时文件由 root 拥有。</p><p><strong>注意：</strong> 对于文件恢复过程中的很多步骤，你可以使用退出（按 <code>q</code> 或“[ Quit ]”）来返回上一步。如果你愿意，可以选择退出选项一直回到该过程中的第一步，也可以选择按下 <code>^c</code> 立即退出。</p><h4 id="恢复训练" tabindex="-1">恢复训练 <a class="header-anchor" href="#恢复训练" aria-label="Permalink to “恢复训练”">​</a></h4><p>使用 <code>testdisk</code> 恢复文件相对来说没有痛苦，但有些复杂。在恐慌时间到来之前，最好先练习一下恢复文件，让自己有机会熟悉这个过程。</p><hr>`,41)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3575524/recovering-deleted-files-on-linux-with-testdisk.html"},{default:i(()=>[...s[3]||(s[3]=[e("https://www.networkworld.com/article/3575524/recovering-deleted-files-on-linux-with-testdisk.html",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[5]||(s[5]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const v=l(c,[["render",h]]);export{m as __pageData,v as default};
